//! Crossings: a `<junction type="crossing">` and its `<roadSection>`s.
//!
//! `tests/data/crossings.xodr` is generated by `crossings.py`.

use xodr::{load_file_with_provenance, Warning};

const FIXTURE: &str = "tests/data/crossings.xodr";

#[test]
fn a_crossing_names_the_stretch_of_each_road_and_its_lanes() {
    let (net, prov) = load_file_with_provenance(FIXTURE).unwrap();
    let [crossing] = net.crossings() else {
        panic!("{:?}", net.crossings());
    };
    assert_eq!(
        (crossing.od_id.as_str(), crossing.name.as_str()),
        ("555", "myRailCrossing")
    );
    let road = |od: &str| net.road_by_od_id(od).unwrap().id();
    let stretches: Vec<_> = crossing
        .sections
        .iter()
        .map(|s| (s.od_id.as_str(), s.road, s.s_start, s.s_end, s.lanes.len()))
        .collect();
    assert_eq!(
        stretches,
        [
            ("0", road("1"), 50.0, 60.0, 2),
            ("1", road("2"), 140.0, 160.0, 1)
        ]
    );
    for lane in &crossing.sections[0].lanes {
        assert!((lane.to - lane.from - 10.0).abs() < 1e-3, "{lane:?}");
    }
    assert!(prov.warnings.contains(&Warning::RoadSectionDropped {
        junction_id: "555".into(),
        road_id: "99".into(),
    }));
    assert_eq!(net.yields_to(road("1")).collect::<Vec<_>>(), [road("2")]);
}
